import React, { useState, useEffect, useRef } from "react";
import { Link, NavLink, useLocation, useSearchParams } from "react-router-dom";

// Импорт логотипов
import plLogo from "../../assets/leagues/premier-league.png";
import blLogo from "../../assets/leagues/bundesliga.png";
import saLogo from "../../assets/leagues/serie-a.png";
import pdLogo from "../../assets/leagues/la-liga.png";
import flLogo from "../../assets/leagues/ligue-1.png";

const leagues = [
  { code: null, name: "ВСЕ ЧЕМПИОНАТЫ", logo: null },
  { code: "Premier_League", name: "Premier League", logo: plLogo },
  { code: "La_Liga", name: "La Liga", logo: pdLogo },
  { code: "Serie_A", name: "Serie A", logo: saLogo },
  { code: "Bundesliga", name: "Bundesliga", logo: blLogo },
  { code: "Ligue_1", name: "Ligue 1", logo: flLogo },
];

function Header() {
  const [isLeagueOpen, setIsLeagueOpen] = useState(false);
  const [searchParams] = useSearchParams();
  const currentLeagueCode = searchParams.get("league");
  const location = useLocation();
  const dropdownRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target)) {
        setIsLeagueOpen(false);
      }
    };
    document.addEventListener("mousedown", handleClickOutside);
    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
      setIsLeagueOpen(false);
    };
  }, [location]);

  // Находим текущую лигу для отображения на кнопке
  const activeLeague =
    leagues.find((l) => l.code === currentLeagueCode) || leagues[0];

  return (
    <header className="bg-gray-950 border-b border-gray-900 sticky top-0 z-[100] w-full">
      <div className="container mx-auto px-4 h-20 flex items-center justify-between gap-4">
        {/* ЛЕВАЯ ЧАСТЬ: Логотип */}
        <Link to="/" className="flex-shrink-0">
          <span className="text-xl lg:text-2xl font-black tracking-tighter text-gradient-neuro-title">
            NeuroPredict
          </span>
        </Link>

        {/* ЦЕНТРАЛЬНАЯ ЧАСТЬ: Поиск (занимает всё свободное место) */}
        <div className="flex-grow max-w-md relative mx-2">
          <input
            type="text"
            placeholder="Поиск..."
            className="w-full bg-gray-900 border border-gray-800 rounded-2xl py-2.5 px-5 text-sm text-gray-300 focus:outline-none focus:ring-1 focus:ring-red-600 transition-all"
          />
        </div>

        {/* ПРАВАЯ ЧАСТЬ: Сравнение + Лиги */}
        <div
          className="flex items-center gap-2 md:gap-4 flex-shrink-0"
          ref={dropdownRef}
        >
          {/* Кнопка H2H Сравнение */}
          <button className="p-2.5 bg-gray-900 border border-gray-800 rounded-xl hover:border-red-600 transition-all group">
            <svg
              className="w-5 h-5 text-gray-500 group-hover:text-red-600"
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="2"
                d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z"
              />
            </svg>
          </button>

          {/* КНОПКА ЛИГ (ИНФОРМАТИВНАЯ) */}
          <div className="relative">
            <button
              onClick={() => setIsLeagueOpen(!isLeagueOpen)}
              className={`flex items-center gap-2 px-3 py-2.5 rounded-xl border-2 transition-all ${
                isLeagueOpen
                  ? "bg-red-600 border-red-600"
                  : "bg-gray-900 border-gray-800 text-gray-300 hover:border-gray-600"
              }`}
            >
              <span className="hidden sm:block text-[10px] font-black uppercase tracking-widest">
                {activeLeague.code ? activeLeague.name : "ЛИГИ"}
              </span>
              <svg
                className={`w-4 h-4 transition-transform ${isLeagueOpen ? "rotate-180" : ""}`}
                fill="none"
                stroke="currentColor"
                viewBox="0 0 24 24"
              >
                <path
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  strokeWidth="2"
                  d="M19 9l-7 7-7-7"
                />
              </svg>
            </button>

            {/* ВЫПАДАЮЩИЙ СПИСОК (СТРОКИ ПО ОДНОЙ) */}
            {isLeagueOpen && (
              <div className="absolute top-full right-0 mt-3 w-[260px] bg-gray-950 border border-gray-800 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2">
                <div className="flex flex-col py-2">
                  {leagues.map((league) => {
                    const isActive =
                      currentLeagueCode === league.code ||
                      (!currentLeagueCode && league.code === null);
                    return (
                      <NavLink
                        key={league.code || "all"}
                        to={league.code ? `/?league=${league.code}` : "/"}
                        className={`flex items-center gap-4 px-4 py-3 transition-colors ${
                          isActive
                            ? "bg-red-600/10 text-white"
                            : "text-gray-400 hover:bg-gray-900 hover:text-white"
                        }`}
                      >
                        {/* Квадратик с логотипом внутри строки */}
                        <div
                          className={`w-10 h-10 rounded-lg flex items-center justify-center flex-shrink-0 ${
                            isActive ? "bg-red-600" : "bg-gray-800"
                          }`}
                        >
                          {league.logo ? (
                            <img
                              src={league.logo}
                              alt=""
                              className="w-7 h-7 object-contain"
                            />
                          ) : (
                            <span className="text-[10px] font-black text-yellow-500">
                              ALL
                            </span>
                          )}
                        </div>
                        <span
                          className={`text-xs font-bold uppercase tracking-tight ${isActive ? "text-red-500" : ""}`}
                        >
                          {league.name}
                        </span>
                        {isActive && (
                          <div className="ml-auto w-1.5 h-1.5 bg-red-600 rounded-full shadow-[0_0_8px_red]"></div>
                        )}
                      </NavLink>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </header>
  );
}

export default Header;
